            "description": "关键词，去前后空格后对书名或作者进行子串匹配，%和_按字面匹配。"
          },
          {
            "name": "sort",
            "in": "query",
            "required": false,
            "schema": {
              "type": "string",
              "enum": [
                "recommended",
                "price-low",
                "price-high"
              ],
              "default": "recommended"
